// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- see below
// @ts-ignore: generated by `opennextjs-cloudflare build`, so missing for tsc
// in CI and present after a local build (where @ts-expect-error would fail).
import openNext from "./.open-next/worker.js";

/* The Worker's entry: OpenNext's generated worker, plus byte ranges for the
   clips under /video. The static asset server answers a Range request with
   the whole file (200, no Accept-Ranges), so a browser cannot seek past what
   it has buffered, and Safari, which asks for a range before it plays, may
   not play the clip at all. wrangler.jsonc sends /video/* here first
   (run_worker_first); every other request reaches OpenNext as before. */
export default {
  fetch(request, env, ctx) {
    if (new URL(request.url).pathname.startsWith("/video/")) {
      return serveClip(request, env);
    }
    return openNext.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<Cloudflare.Env>;

// One range per request, which is all a <video> asks for: "bytes=0-",
// "bytes=100-199" or the last N bytes, "bytes=-500". Anything else gets the
// whole file, as HTTP allows.
const RANGE = /^bytes=(\d*)-(\d*)$/;

async function serveClip(request: Request, env: Cloudflare.Env): Promise<Response> {
  const range =
    request.method === "GET" ? RANGE.exec(request.headers.get("Range") ?? "") : null;
  if (!range || (!range[1] && !range[2])) return env.ASSETS.fetch(request);

  const asset = await env.ASSETS.fetch(request.url);
  // A partial copy the browser holds of an older file must not be patched
  // with bytes of this one: If-Range names the version it has.
  const ifRange = request.headers.get("If-Range");
  if (!asset.ok || (ifRange && ifRange !== asset.headers.get("ETag"))) return asset;

  // The largest clip is 4.3 MB, so the whole file in memory is fine.
  const body = await asset.arrayBuffer();
  const size = body.byteLength;
  const start = range[1] ? Number(range[1]) : Math.max(size - Number(range[2]), 0);
  const end = range[1] && range[2] ? Math.min(Number(range[2]), size - 1) : size - 1;
  if (start > end) {
    return new Response(null, {
      status: 416,
      headers: { "Content-Range": `bytes */${size}` },
    });
  }

  const headers = new Headers(asset.headers);
  headers.set("Accept-Ranges", "bytes");
  headers.set("Content-Range", `bytes ${start}-${end}/${size}`);
  headers.set("Content-Length", String(end - start + 1));
  return new Response(body.slice(start, end + 1), { status: 206, headers });
}
